        raise TypeError('add_lists: `lst` must be a list of integers; nothing was proved for anything else')
    if not (_t_ints(tup, 1)):
        raise TypeError('add_lists: `tup` must be a list of integers; nothing was proved for anything else')
    lst = _t_tuple(lst)
    tup = _t_tuple(tup)
    _t_result = _t_core(lst, tup)
